import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import {PNG} from 'pngjs';
import {DAMAGE_SPRITE_FRAMES as D} from '../../../../src/js/toy-room/DamageSpriteFrames.js';
import {sampleArenaPlayerAnimation} from '../../../../src/js/toy-room/ArenaPlayerAnimation.js';
const sizes={girl:[296,303],train:[201,139],robot:[148,236],dinosaur:[218,205],bear:[144,177]};
for(const [actor,clip]of Object.entries(D)){
 assert.equal(clip.frames.length,6);const hashes=new Set();
 for(const f of clip.frames){const bytes=await fs.readFile('assets/art/toy-room/battle/'+f.file),p=PNG.sync.read(bytes);
  assert.deepEqual([p.width,p.height],sizes[actor],'Resolução original preservada');
  let opaque=0,clear=0,edge=0;
  for(let y=0;y<p.height;y++)for(let x=0;x<p.width;x++){const a=p.data[(y*p.width+x)*4+3];if(a>128)opaque++;if(a===0)clear++;if((x===0||y===0||x===p.width-1||y===p.height-1)&&a>0)edge++;}
  assert.ok(opaque>200&&clear>200,'Arte visível e transparente');assert.equal(edge,0,'Quadro sem corte nas bordas');hashes.add(f.sha256);
 }
 assert.equal(hashes.size,6,'Seis poses distintas por ator');
}
const chosen=new Set();
for(let age=0;age<22;age++){
 const s={mode:'BATTLE',playerHitTime:22-age,playerAnimation:{pose:'damage',poseTime:age,blendTime:8,attackAge:24,attackDirection:1,attackSerial:0}};
 const sample=sampleArenaPlayerAnimation(s,{facing:'left'});chosen.add(JSON.stringify([sample.layers[0].frame.file,sample.layers[0].frame.x,sample.layers[0].frame.y]));
 assert.equal(sample.pose,'damage');assert.equal(sample.slash,null,'Dor não desenha golpe');
 const before=JSON.stringify(s);sampleArenaPlayerAnimation(s,{facing:'right'});assert.equal(JSON.stringify(s),before,'Render não avança dano');
}
assert.equal(chosen.size,6,'Todos os quadros de dor são alcançados durante a reação');
console.log('APROVADO: 30 PNGs, cinco resoluções nativas, transparência, bordas, poses distintas e seis etapas de dano alcançadas sem alterar estado.');

const interrupted={mode:'BATTLE',playerHitTime:22,playerAnimation:{pose:'attack',poseTime:3,blendTime:8,attackAge:5,attackDirection:1,attackSerial:1}};
const instant=sampleArenaPlayerAnimation(interrupted,{facing:'left'});
assert.equal(instant.pose,'damage','Dor tem prioridade no hitstop');
assert.ok(instant.layers[0].frame.file.endsWith('arena-dano.png') && instant.layers[0].frame.x === 12 && instant.layers[0].frame.y === 12,'Impacto inicia no primeiro quadro');
assert.equal(instant.slash,null,'Golpe interrompido não conserva arco de espada');
console.log('APROVADO: dor imediata no hitstop e ataque interrompido sem arco residual.');
